cat > 99_test.sql <<'EOF'
\set ON_ERROR_STOP 0
insert into auth.users values ('00000000-0000-0000-0000-00000000000a'),('00000000-0000-0000-0000-00000000000b'),('00000000-0000-0000-0000-00000000000c');
insert into teams values ('10000000-0000-0000-0000-000000000001','T1'),('20000000-0000-0000-0000-000000000002','T2');
-- a: admin T1, b: member T1, c: admin T2
insert into team_members values ('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-00000000000a','admin'),('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-00000000000b','member'),('20000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-00000000000c','admin');
insert into projects (team_id,name) values ('10000000-0000-0000-0000-000000000001','P1'),('20000000-0000-0000-0000-000000000002','P2');
\echo == anon
set role anon; select count(*) from teams; select count(*) from project_overview; reset role;
\echo == b (member T1)
set role authenticated; set request.jwt.claim.sub='00000000-0000-0000-0000-00000000000b';
select name from teams; select count(*) members from team_members; select name from project_overview;
insert into projects (team_id,name) values ('10000000-0000-0000-0000-000000000001','nope');
update projects set name='x' returning *; delete from team_members returning *;
insert into team_members values ('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-00000000000c','member');
select private.is_team_admin('20000000-0000-0000-0000-000000000002');
\echo == a (admin T1)
set request.jwt.claim.sub='00000000-0000-0000-0000-00000000000a';
insert into projects (team_id,name) values ('10000000-0000-0000-0000-000000000001','new') returning name, created_by;
insert into projects (team_id,name) values ('20000000-0000-0000-0000-000000000002','evil');
update projects set team_id='20000000-0000-0000-0000-000000000002' where name='P1';
update projects set name='P1-renamed' where name='P1' returning name;
update projects set name='hack' where name='P2' returning name;
insert into team_members values ('10000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-00000000000c','member') returning user_id;
insert into team_members values ('20000000-0000-0000-0000-000000000002','00000000-0000-0000-0000-00000000000a','admin');
delete from team_members where user_id='00000000-0000-0000-0000-00000000000c' returning team_id;
delete from projects returning name;
reset role; select name from projects order by 1;
EOF
docker run --rm -d --name rlspg -e POSTGRES_PASSWORD=x postgres:16 >/dev/null && until docker exec rlspg pg_isready -U postgres -q 2>/dev/null; do sleep 1; done; sleep 2
for f in 00_stub.sql $R/20260101000000_init.sql $R/20261022000000_enable_rls.sql; do docker exec -i rlspg psql -U postgres -v ON_ERROR_STOP=1 -q < $f || echo "FAILED $f"; done
docker exec -i rlspg psql -U postgres -q < 99_test.sql 2>&1; docker rm -f rlspg >/dev/null

